from pathlib import Path
import json,subprocess,hashlib,html
root=Path(__file__).resolve().parents[1]; d=root/'docs/rapier-trial'
ffmpeg=subprocess.check_output(['/tmp/mabear-media-check-env/bin/python','-c','import imageio_ffmpeg; print(imageio_ffmpeg.get_ffmpeg_exe())'],text=True).strip()
clips=[('obstacle','baseline','Masha and the bench',9.274),('drop','control','A released ball',8),('regression','baseline','Hug and shoulder ride',15.482)]
for name,before,title,duration in clips:
 subprocess.run([ffmpeg,'-v','error','-y','-i',str(d/before/f'{name}.mp4'),'-i',str(d/'after'/f'{name}.mp4'),'-filter_complex',f'[0:v]fps=30,scale=960:576,setsar=1[l];[1:v]fps=30,scale=960:576,setsar=1[r];[l][r]hstack=inputs=2[v]','-map','[v]','-t',str(duration),'-c:v','libx264','-crf','20','-pix_fmt','yuv420p','-movflags','+faststart',str(d/f'{name}-comparison.mp4')],check=True)
concat=d/'montage-input.txt';concat.write_text(''.join(f"file '{name}-comparison.mp4'\n" for name,_,_,_ in clips))
subprocess.run([ffmpeg,'-v','error','-y','-f','concat','-safe','0','-i',str(concat),'-c','copy','-movflags','+faststart',str(d/'before-after.mp4')],check=True)
media=[]
for video in [*d.glob('*comparison.mp4'),d/'before-after.mp4',*d.glob('baseline/*.mp4'),*d.glob('control/*.mp4'),*d.glob('after/*.mp4')]:
 result=subprocess.run([ffmpeg,'-v','error','-xerror','-i',str(video),'-an','-fps_mode','passthrough','-enc_time_base','demux','-progress','pipe:1','-nostats','-f','null','-'],capture_output=True,text=True,check=True)
 tail=subprocess.run([ffmpeg,'-v','error','-xerror','-sseof','-2','-i',str(video),'-an','-f','null','-'],capture_output=True,text=True,check=True)
 media.append({'file':str(video.relative_to(d)),'bytes':video.stat().st_size,'sha256':hashlib.sha256(video.read_bytes()).hexdigest(),'decoded':True,'tailDecoded':True,'progress':result.stdout.strip().split('progress=')[-2] if 'progress=' in result.stdout else result.stdout})
(d/'media-check.json').write_text(json.dumps(media,indent=2))
proofs={mode:json.loads((d/mode/'proof.json').read_text()) for mode in ['baseline','control','after']}
rows=''
for name,before,_,_ in clips:
 for mode in [before,'after']:
  b=next(v for v in proofs[mode]['benchmarks'] if v['id']==name)
  rows+=f"<tr><td>{name}</td><td>{mode}</td><td>{b['meanFps']:.1f}</td><td>{b['gapP95']:.1f}</td><td>{b['evalP95']:.2f}</td><td>{b['coldMs']:.1f}</td></tr>"
sections=''.join(f'''<section><h2>{html.escape(title)}</h2><p>{'The new drop cue uses an animation-only control; it did not exist in the pre-trial release.' if name=='drop' else 'Before uses the exact pre-trial source and assets.'}</p><video controls preload="metadata" playsinline src="{name}-comparison.mp4"></video><p><a href="{before}/{name}.mp4">Before / control</a> · <a href="after/{name}.mp4">After</a></p></section>''' for name,before,title,_ in clips)
page=f'''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Bounded Rapier trial — evidence</title><style>*{{box-sizing:border-box}}body{{margin:0;background:#f5f3e9;color:#22382b;font:17px/1.55 system-ui}}main{{max-width:1160px;margin:auto;padding:40px 24px}}h1{{font-size:clamp(32px,4vw,52px);line-height:1.08;max-width:800px}}h2{{margin-top:0}}.tag{{letter-spacing:.13em;font-size:12px;font-weight:750;text-transform:uppercase}}.lead{{font-size:21px;max-width:850px}}section{{background:white;padding:24px;margin:24px 0;border:1px solid #d8dfd3;border-radius:12px}}video{{width:100%;display:block;background:#131b16;border-radius:8px}}a{{color:#1b633e}}table{{border-collapse:collapse;width:100%;font-size:15px}}th,td{{border-bottom:1px solid #d8dfd3;padding:10px;text-align:left}}.scroll{{overflow:auto}}.note{{font-size:14px;color:#56645a}}.badge{{display:inline-block;padding:6px 12px;border-radius:20px;background:#dae8d5}}footer{{margin-top:32px;font-size:14px}}</style><main><div class="tag">Mabear · Local engineering trial · 7 November 2026</div><h1>Physical contact without replacing the animation system.</h1><p class="lead">Masha stops at the bench and slides around it. A released ball lands on the bench, rebounds and settles. Seeking reuses the same trajectory.</p><span class="badge">Opt-in deployed · No generation services</span><p><a href="https://mabear-storybook.ilya-baimetov.workers.dev/physics/">Open live demo</a> · <a href="deployment/deployment.json">Deployment evidence</a></p><section><h2>Watch the matched comparison</h2><video controls preload="metadata" playsinline poster="after/obstacle-2.00.png" src="before-after.mp4"></video><p class="note">Left: pre-trial baseline or labelled drop control. Right: Rapier. Actual Three.js rendering, loaded rigs and story timelines; silent recordings at real 1× speed. Contact stories use matched authored coverage. The regression keeps its production cameras.</p></section>{sections}<section><h2>Measured on this device</h2><p>MacBook Pro · Apple M1 Max · 32 GB · macOS 27.2 · Chrome 156 / Metal · 1280×720 · fixed rendering quality. Six-second measurements per scene; these are local samples, not a device matrix.</p><div class="scroll"><table><thead><tr><th>Story</th><th>Mode</th><th>Mean FPS</th><th>Frame p95 ms</th><th>Evaluation p95 ms</th><th>Cold seek ms</th></tr></thead><tbody>{rows}</tbody></table></div><p class="note">Rendering, evaluation and recording are measured separately. Cold seek means the first query at the end of that story, before caching. <a href="after/proof.json">Raw measurement and source evidence</a>.</p></section><section><h2>What the result supports</h2><p><strong>Continue with selective integration.</strong> Static obstacles and loose objects benefit. Whole-character physics is not justified by this trial.</p><p>Only the covered central yard, Masha’s capsule and one ball are simulated. Hugs, rides, pickups, other characters and locations retain animation ownership. Blocked movement changes the destination reached; the compiler does not yet replan subsequent interaction marks. Later pickup of a settled ball still uses its semantic mark. Actor/ball collision is excluded. These are rollout blockers, not completed features.</p><p>The Rapier chunk adds about 1.67 MB compressed, loaded by the demo or explicit editor flag. Long uncached seeks still need background precomputation before wider use. Stories over 180 seconds fall back to animation.</p></section><footer><a href="README.md">Results and reproduction</a> · <a href="ARCHITECTURE.md">Ownership and cache design</a> · <a href="adversarial-review.md">Independent adversarial review</a> · <a href="ui/proof.json">Actual editor controls</a> · <a href="media-check.json">Video decode checks</a></footer></main></html>'''
(d/'index.html').write_text(page)
print(json.dumps({'media':len(media),'comparison':str(d/'before-after.mp4'),'report':str(d/'index.html')}))
